import{_ as r}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as e,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Cloud Agents","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/cursor/cloud-agents.md","filePath":"zh/products/ai-coding/cursor/cloud-agents.md","lastUpdated":1787044708000}'),s={name:"zh/products/ai-coding/cursor/cloud-agents.md"};function n(d,t,l,c,i,u){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="cloud-agents" tabindex="-1">Cloud Agents <a class="header-anchor" href="#cloud-agents" aria-label="Permalink to &quot;Cloud Agents&quot;">​</a></h1><p>Cloud Agents 用同一套 <a href="https://cursor.com/learn/agents" target="_blank" rel="noreferrer">agent fundamentals</a>，但跑在<strong>隔离 VM</strong> 里，环境接近你本机：克隆仓库、装依赖、密钥、启动命令、网络。</p><blockquote><p>官方：<a href="https://cursor.com/docs/cloud-agent" target="_blank" rel="noreferrer">Cloud Agents</a>。<strong>曾用名 Background Agents</strong> — 一个产品，不是两个。</p><p>本页讲<strong>形态</strong>：何时用、怎么开、和本机差在哪。任务配方留在 <a href="./cursor-cookbook.html#派-cloud-agent-干活">Cookbook</a>。</p></blockquote><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><ul><li><strong>付费</strong> Cursor 计划</li><li>账号<strong>管理员</strong>已接源代码托管：<a href="https://cursor.com/docs/integrations/github" target="_blank" rel="noreferrer">GitHub</a>、<a href="https://cursor.com/docs/integrations/gitlab" target="_blank" rel="noreferrer">GitLab</a>、<a href="https://cursor.com/docs/integrations/bitbucket" target="_blank" rel="noreferrer">Bitbucket Cloud</a> 或 <a href="https://cursor.com/docs/integrations/azure-devops" target="_blank" rel="noreferrer">Azure DevOps</a></li><li>对仓库（以及依赖仓 / 子模块）有读写权限</li><li>接受官方说法：Cloud 是需要 Cursor <strong>存代码</strong>的功能。策略禁止存储就不要开</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完本页你能：</p><ol><li>在 Cloud、本机 Agent、Bugbot、CLI 之间做选择</li><li>从桌面、网页、手机 / PWA、Slack、GitHub、Linear 或 <code>agent</code> + <code>&amp;</code> 发起</li><li>把<strong>环境配置</strong>当成主杠杆</li><li>知道 VM 上 MCP / Hooks 的官方限制</li></ol><hr><h2 id="为什么用-cloud-agents" tabindex="-1">为什么用 Cloud Agents <a class="header-anchor" href="#为什么用-cloud-agents" aria-label="Permalink to &quot;为什么用 Cloud Agents&quot;">​</a></h2><ul><li><strong>想开多少条并行就开多少条</strong></li><li>笔记本<strong>不必</strong>保持在线</li><li>VM 可以 <strong>build、测试、操作</strong>改过的软件，包括桌面 / 浏览器 computer use</li><li>团队 <a href="https://cursor.com/docs/mcp" target="_blank" rel="noreferrer">MCP</a>（HTTP 和 stdio；需要时支持 OAuth）</li><li><strong>多仓</strong>环境：看完整工作区、协调改动、在改过的仓<strong>各开一个 PR</strong>。官方：<strong>多仓暂不支持 long-running</strong></li></ul><p>官方原文：不配环境就像不给工程师电脑。</p><h2 id="从哪发起" tabindex="-1">从哪发起 <a class="header-anchor" href="#从哪发起" aria-label="Permalink to &quot;从哪发起&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>怎么开</th></tr></thead><tbody><tr><td><strong>Cursor Desktop</strong></td><td>Agent 输入框下拉选 <strong>Cloud</strong></td></tr><tr><td><strong>Cursor Web</strong></td><td>任意设备打开 <a href="https://cursor.com/agents" target="_blank" rel="noreferrer">cursor.com/agents</a></td></tr><tr><td><strong>Cursor for iOS</strong></td><td>原生应用 — <a href="https://cursor.com/docs/cloud-agent/mobile" target="_blank" rel="noreferrer">mobile</a></td></tr><tr><td><strong>Android</strong></td><td>Chrome 打开 <a href="https://cursor.com/agents" target="_blank" rel="noreferrer">cursor.com/agents</a> → <strong>Install App</strong>（PWA）</td></tr><tr><td><strong>Slack / Linear</strong></td><td><code>@cursor</code>（管理员先装集成）</td></tr><tr><td><strong>GitHub / Bitbucket</strong></td><td>在 PR 或（GitHub）issue 评论 <code>@cursor</code></td></tr><tr><td><strong>API</strong></td><td>Cloud Agents API</td></tr><tr><td><strong>Cursor CLI</strong></td><td>消息前加 <code>&amp;</code> — 见 <a href="./cursor-cli.html">CLI</a></td></tr></tbody></table><p>不要把「光标旁三行」丢到这里 — 那是 Tab。不要用 Cloud 当 PR 审查 — 那是 <a href="./cursor-cookbook.html#用-bugbot-审-pr">Bugbot</a>。</p><h2 id="它怎么跑" tabindex="-1">它怎么跑 <a class="header-anchor" href="#它怎么跑" aria-label="Permalink to &quot;它怎么跑&quot;">​</a></h2><ol><li>Cloud 从已接的提供方克隆到<strong>单独分支</strong></li><li>Agent 在配好的环境里干活</li><li>push 并交接（常见是可合并的 PR + artifacts）</li></ol><p>环境可以用 agent-led setup、保存的 snapshot，或通过 <code>.cursor/environment.json</code> 指 Dockerfile。见 <a href="https://cursor.com/docs/cloud-agent/setup" target="_blank" rel="noreferrer">Cloud agent setup</a>。<a href="https://cursor.com/docs/cloud-agent/builds" target="_blank" rel="noreferrer">Builds</a> 在后台准备仓库和依赖。</p><p>在 agent 页把鼠标放到仓库名上，能看到这次运行用的环境和 Build。</p><p>运行时控制（官方）：密钥、出站域名白名单、Tailscale 一类的私网、受支持 SCM 路径的私有连接。全集：<a href="https://cursor.com/docs/cloud-agent/security-network" target="_blank" rel="noreferrer">Security and network</a>。</p><h2 id="mcp-和-hooks-官方限制" tabindex="-1">MCP 和 Hooks（官方限制） <a class="header-anchor" href="#mcp-和-hooks-官方限制" aria-label="Permalink to &quot;MCP 和 Hooks（官方限制）&quot;">​</a></h2><p><strong>MCP：</strong> 来自 <a href="https://cursor.com/agents" target="_blank" rel="noreferrer">cursor.com/agents</a> 上的团队 MCP 下拉。HTTP 和 stdio。支持 OAuth。内置 <a href="https://cursor.com/docs/cloud-agent/capabilities.md#cursor-cloud-mcp" target="_blank" rel="noreferrer">Cursor Cloud MCP</a> 做运行诊断（transcript、事件、环境、setup 日志）。</p><p><strong>Hooks：</strong> 只跑仓库 <strong><code>.cursor/hooks.json</code></strong> 里的 command-based 钩子。Enterprise 还会跑团队钩子和企业托管钩子。只读探索的早期回合<strong>不跑</strong>；Agent 拿到可写环境后才开始。</p><p>Cloud 上没有：</p><ul><li>用户级 <code>~/.cursor/hooks.json</code>（VM 读不到你的 home）</li><li>IDE 专用钩子（Tab hooks、<code>workspaceOpen</code>）</li></ul><p>支持的家族包括工具 / 文件钩子（<code>preToolUse</code>、<code>beforeShellExecution</code>、<code>afterFileEdit</code>）和生命周期钩子（<code>beforeSubmitPrompt</code>、<code>subagentStart</code> / <code>subagentStop</code>、<code>preCompact</code>、<code>afterAgentResponse</code> / <code>afterAgentThought</code>、<code>stop</code>）。对照表：<a href="https://cursor.com/docs/hooks.md#cloud-agent-support" target="_blank" rel="noreferrer">Hooks · Cloud agent support</a>。</p><h2 id="artifacts、桌面、分享" tabindex="-1">Artifacts、桌面、分享 <a class="header-anchor" href="#artifacts、桌面、分享" aria-label="Permalink to &quot;Artifacts、桌面、分享&quot;">​</a></h2><ul><li><strong>Artifacts：</strong> 截图、录像、日志 — 改了什么、怎么验收</li><li><strong>远程桌面：</strong> 接管 Agent 桌面验收，不必本地 checkout；交还控制权让它继续</li><li><strong>分享：</strong> 发 agent URL。查看者必须在<strong>同一个 Cursor 团队</strong>，并且用<strong>自己的</strong> SCM 账号对该仓有权限。光是团队成员不够。默认只读，除非管理员打开 <a href="https://cursor.com/docs/cloud-agent/settings.md#team-follow-ups" target="_blank" rel="noreferrer">team follow-ups</a></li></ul><h2 id="模型和计费" tabindex="-1">模型和计费 <a class="header-anchor" href="#模型和计费" aria-label="Permalink to &quot;模型和计费&quot;">​</a></h2><p>Cloud Agents 用一组精选模型。受支持的模型可选上下文窗口。窗口更大，token 和费用可能更高。</p><p>按所选 <a href="https://cursor.com/docs/models-and-pricing.md#model-pricing" target="_blank" rel="noreferrer">模型</a> 的 <strong>API 定价</strong>计费。第一次用时要设花费上限。</p><h2 id="手机、jetbrains、plugins、automations" tabindex="-1">手机、JetBrains、Plugins、Automations <a class="header-anchor" href="#手机、jetbrains、plugins、automations" aria-label="Permalink to &quot;手机、JetBrains、Plugins、Automations&quot;">​</a></h2><p>导航级一行，官方页，不另开教程：</p><table tabindex="0"><thead><tr><th>入口</th><th>官方一句话</th></tr></thead><tbody><tr><td><strong>iOS / PWA</strong></td><td>原生 iOS（beta，iOS / iPadOS 26+）发起和审查 Cloud Agents。Android：装 PWA。<a href="https://cursor.com/docs/cloud-agent/mobile" target="_blank" rel="noreferrer">Mobile</a></td></tr><tr><td><strong>JetBrains</strong></td><td>IntelliJ / PyCharm / WebStorm 里的 ACP agent。付费计划 + AI Assistant 2025.1+。<a href="https://cursor.com/docs/integrations/jetbrains" target="_blank" rel="noreferrer">JetBrains</a></td></tr><tr><td><strong>Xcode</strong></td><td>Xcode 26.3+ 内置 MCP：构建、测试、SwiftUI 预览、Apple 文档。<a href="https://cursor.com/docs/integrations/xcode" target="_blank" rel="noreferrer">Xcode</a></td></tr><tr><td><strong>Plugins</strong></td><td>打包 rules、skills、agents、commands、MCP、hooks。<a href="https://cursor.com/docs/plugins" target="_blank" rel="noreferrer">Plugins</a></td></tr><tr><td><strong>Automations</strong></td><td>按日程或事件跑 Cloud Agents（GitHub、GitLab、Slack、webhook、Linear …）。该页上三个 Cursor 托管 Agent 是 Bugbot、Security Agents、PR Routing。<a href="https://cursor.com/docs/cloud-agent/automations" target="_blank" rel="noreferrer">Automations</a></td></tr></tbody></table><h2 id="什么时候用" tabindex="-1">什么时候用 <a class="header-anchor" href="#什么时候用" aria-label="Permalink to &quot;什么时候用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>派 Cloud</th><th>留在本机</th></tr></thead><tbody><tr><td>人不在、隔夜、要并行很多条</td><td>你要盯 diff、改计划、用 Debug Mode</td></tr><tr><td>隔离 VM + 测试 + PR</td><td>密钥 / 服务从没离开过你的机器</td></tr><tr><td>跨仓协调并分别开 PR</td><td>单仓、你已经 checkout 好了</td></tr></tbody></table><p>任务配方（environment.json、AGENTS.md 标题、派发清单）：<a href="./cursor-cookbook.html#派-cloud-agent-干活">Cookbook · Cloud</a>。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>陷阱</th><th>正确做法</th></tr></thead><tbody><tr><td>不配环境</td><td>Agent-led setup 或 <code>.cursor/environment.json</code> + Secrets 页</td></tr><tr><td>指望本机 <code>mcp.json</code> / <code>~/.cursor/hooks.json</code></td><td>团队 MCP 在 cursor.com/agents；只跑<strong>项目</strong> command hooks</td></tr><tr><td>用 Cloud 当 PR 审查</td><td><a href="./cursor-cookbook.html#用-bugbot-审-pr">Bugbot</a></td></tr><tr><td>为三行代码起一台 VM</td><td>Tab 或 <code>Cmd+K</code></td></tr><tr><td>多仓还要 <strong>long-running</strong></td><td>官方：<strong>还不能</strong></td></tr><tr><td>同事打不开你的运行</td><td>同一团队 <strong>并且</strong> 他自己对该仓有 SCM 权限</td></tr><tr><td>把 <code>.env.local</code> 打进 snapshot 就完事</td><td>官方更推荐 <strong>Secrets</strong> 页</td></tr><tr><td>把 “Background Agents” 写成第二个产品</td><td>同一产品，新名字是 Cloud Agents</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./cursor-cookbook.html#派-cloud-agent-干活">Cookbook · Cloud</a> — 配方</li><li><a href="./cursor-cli.html">Cursor CLI</a> — 终端里 <code>&amp;</code> 交接</li><li><a href="./security-agents.html">Security Agents</a> / <a href="./pr-routing.html">PR Routing</a> — 跑在 Cloud 上的 Automations</li><li><a href="./origin.html">Origin</a> — Cloud 可以对 Origin remote 干活</li><li>官方：<a href="https://cursor.com/docs/cloud-agent" target="_blank" rel="noreferrer">Overview</a>、<a href="https://cursor.com/docs/cloud-agent/setup" target="_blank" rel="noreferrer">Setup</a>、<a href="https://cursor.com/docs/cloud-agent/capabilities" target="_blank" rel="noreferrer">Capabilities</a>、<a href="https://cursor.com/docs/cloud-agent/security-network" target="_blank" rel="noreferrer">Security</a></li></ul>',41)])])}const f=r(s,[["render",n]]);export{m as __pageData,f as default};
